def parse_date(value: str):
    """Return a datetime.date for a strict YYYY-MM-DD string, or None."""
    m = DATE_RE.match(value)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def is_sku(value: str) -> bool:
    return bool(SKU_RE.match(value))


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog: Dict[str, Product] = {}
    for n, raw in iter_lines(text):
        fields = [f.strip(WS) for f in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(n, "expected 4 or 5 fields separated by '|', found {}".format(len(fields)))
        sku, name, price, reorder = fields[:4]
        if not is_sku(sku):
            raise ParseError(n, "bad SKU {!r}".format(sku))
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(n, "duplicate SKU {}".format(sku))
        if name == "":
            raise ParseError(n, "empty name")
        if not PRICE_RE.match(price):
            raise ParseError(n, "bad price {!r}".format(price))
        value = Decimal(price)
        with localcontext() as ctx:
            ctx.prec = max(ctx.prec, value.adjusted() + 3)
            value = value.quantize(CENT)
        if value < CENT:
            raise ParseError(n, "price must be at least 0.01")
        if not WHOLE_RE.match(reorder):
            raise ParseError(n, "bad reorder level {!r}".format(reorder))
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(n, "bad tax {!r} (standard, reduced or zero)".format(fields[4]))
        catalog[sku] = Product(sku, name, value, int(reorder), tax)
    return catalog


def _parse_movement_lines(text: str, catalog) -> List[Tuple[int, Movement]]:
    result = []
    for n, raw in iter_lines(text):
        parts = SEP_RE.split(raw.strip(WS), maxsplit=3)
        if len(parts) < 3:
            raise ParseError(n, "expected DATE SKU QUANTITY [NOTE]")
        date_s, sku, qty = parts[0], parts[1], parts[2]
        note = parts[3].strip(WS) if len(parts) == 4 else ""
        date = parse_date(date_s)
        if date is None:
            raise ParseError(n, "bad date {!r}".format(date_s))
